import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.CVt6dz2a.js";const g=JSON.parse('{"title":"EP.11 综合实战与性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.11-capstone-performance.md","filePath":"comics/EP.11-capstone-performance.md","lastUpdated":1792595797000}'),n={name:"comics/EP.11-capstone-performance.md"};function r(d,t,o,l,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="ep-11-综合实战与性能优化" tabindex="-1">EP.11 综合实战与性能优化 <a class="header-anchor" href="#ep-11-综合实战与性能优化" aria-label="Permalink to &quot;EP.11 综合实战与性能优化&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/11-capstone/basics">11.1 基础入门：项目整合与性能优化</a> 延伸阅读：<a href="./../guide/11-capstone/advanced">进阶篇</a> · <a href="./../guide/11-capstone/practice">实战篇</a> 动手演示：<a href="./../public/demos/capstone/bootstrap.html">bootstrap 分层启动骨架</a> · <a href="./../public/demos/capstone/integrated-scene.html">integrated-scene 整合场景</a> · <a href="./../public/demos/capstone/optimization-lab.html">optimization-lab 两千立方体实验台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君摆了 2000 个独立立方体，<code>renderer.info.render.calls</code> 也是 2000，帧率掉到个位数。</td></tr><tr><td>② 揭秘</td><td>码叔出示合批三选一：独立 Mesh 2000 calls；InstancedMesh ≈1 call 且逐实例可动可拾取；mergeGeometries ≈1 call 但是静态烘焙。先回答&quot;它们还要不要单独动&quot;。</td></tr><tr><td>③ 实证</td><td>像素酱把代码拆成 App → Stage → WorldBuilder → Loop 五层，循环里钳制 dt、用 info 面板实时盯 calls/triangles，远处加 LOD、离场物体走 dispose，帧率回升。</td></tr><tr><td>④ 结案</td><td>码叔总结：性能优化不靠手感，靠 calls 和 triangles 两个指标驱动决策；毕业快乐，从一个黑屏到一座能跑的城。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-五层架构-单向依赖" tabindex="-1">① 五层架构：单向依赖 <a class="header-anchor" href="#_1-五层架构-单向依赖" aria-label="Permalink to &quot;① 五层架构：单向依赖&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>职责</th></tr></thead><tbody><tr><td><strong>App</strong></td><td>入口与装配：读取配置、new 出下面四层并串联</td></tr><tr><td><strong>Stage</strong></td><td>renderer / scene / camera / controls 与画布、resize、pixelRatio</td></tr><tr><td><strong>WorldBuilder</strong></td><td>只负责&quot;往场景里放东西&quot;：灯光、地面、物体、合批策略</td></tr><tr><td><strong>Loop</strong></td><td>setAnimationLoop、dt 计算与钳制、更新与渲染顺序</td></tr><tr><td>（交互层）</td><td>Raycaster / DragControls，只读 Stage 与 WorldBuilder 暴露的对象</td></tr></tbody></table><p>依赖方向严格单向（App 持有一切，下层不反向 import 上层），加功能时知道该改哪一层，避免&quot;所有逻辑糊在一个 main.js&quot;。</p><h3 id="_2-dt-钳制" tabindex="-1">② dt 钳制 <a class="header-anchor" href="#_2-dt-钳制" aria-label="Permalink to &quot;② dt 钳制&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> dt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(timer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getDelta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.05</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 切后台/卡帧后最多前进 50ms</span></span></code></pre></div><p>防止标签页切回时物体穿越、碰撞系统爆炸。</p><h3 id="_3-合批三选一" tabindex="-1">③ 合批三选一 <a class="header-anchor" href="#_3-合批三选一" aria-label="Permalink to &quot;③ 合批三选一&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>calls</th><th>可否单独动</th><th>适用</th></tr></thead><tbody><tr><td>2000 个独立 Mesh</td><td>2000</td><td>✅ 完全独立</td><td>物体数量少、材质各异</td></tr><tr><td><strong>InstancedMesh</strong></td><td>≈1</td><td>✅ 逐实例矩阵/颜色</td><td>草丛、人群、树、可拾取阵列</td></tr><tr><td><strong>mergeGeometries</strong></td><td>≈1</td><td>❌ 烤成一个网格</td><td>静态建筑、远景、地形装饰</td></tr></tbody></table><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// InstancedMesh 写入后必须通知 GPU</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">instanced.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMatrixAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i, matrix)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">instanced.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setColorAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i, color)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">instanced.instanceMatrix.needsUpdate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (instanced.instanceColor) instanced.instanceColor.needsUpdate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><p>合并的前提是<strong>材质相同</strong>；不同材质的网格无法合为一次绘制。</p><h3 id="_4-lod-与资源释放" tabindex="-1">④ LOD 与资源释放 <a class="header-anchor" href="#_4-lod-与资源释放" aria-label="Permalink to &quot;④ LOD 与资源释放&quot;">​</a></h3><ul><li><strong>LOD（细节层次）</strong>：<code>lod.addLevel(meshHigh, 0)</code>、<code>addLevel(meshMid, 30)</code>、<code>addLevel(meshLow, 80)</code>，相机距离自动切换模型精度；</li><li><strong>dispose 三件套</strong>：离场对象遍历释放 <code>geometry.dispose()</code>、<code>material.dispose()</code>，材质中的贴图还要 <code>texture.dispose()</code>；释放后看 <code>renderer.info.memory</code> 验证；</li><li><strong>量化决策</strong>：每帧读 <code>renderer.info.render.calls</code> 与 <code>.triangles</code>，优化前后用数字对比，不靠&quot;感觉流畅了&quot;。</li></ul><h3 id="_5-上线清单" tabindex="-1">⑤ 上线清单 <a class="header-anchor" href="#_5-上线清单" aria-label="Permalink to &quot;⑤ 上线清单&quot;">​</a></h3><ul><li><code>setPixelRatio(Math.min(devicePixelRatio, 2))</code> 封顶，移动端可降到 1.5；</li><li>阴影按设备分档（mapSize 1024/2048）；</li><li>移动端真机实测（桌面模拟器不能代表真实 GPU/散热）；</li><li>提供 WebGL 不可用时的降级提示（检测 WebGLRenderingContext 创建结果）。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：InstancedMesh 颜色不更新？</strong> setColorAt 首次调用才会创建 instanceColor，之后要置 <code>instanceColor.needsUpdate = true</code>。</li><li><strong>Q：merge 之后还想点选其中一把椅子？</strong> 不行——合并后它只是一个大网格的一部分；需要独立拾取就选 InstancedMesh（读 instanceId）。</li><li><strong>Q：remove(mesh) 之后显存没降？</strong> 从场景树移除只停止渲染，geometry/material/texture 仍占 GPU 资源，必须逐一 dispose。</li><li><strong>Q：calls 不高但还是卡？</strong> 看 triangles（顶点/片元过重）、阴影 Pass 数量、后处理链与 JS 主线程耗时；calls 只反映提交次数。</li><li><strong>Q：2000 个不同颜色材质为什么合批失败？</strong> 材质不同无法合批；改用 InstancedMesh + instanceColor，或合并到带顶点色的单一材质。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>2000 个相同材质的静态装饰柱与 2000 棵需要独立摇曳、可被点选的树，分别选哪种合批方案？</li><li>使用 InstancedMesh 设置完每个实例的矩阵后，必须设置哪个属性？为什么？</li><li>从场景移除一个物体并释放显存，需要 dispose 哪三类资源？用什么对象验证释放结果？</li></ol><details><summary>答案</summary><ol><li>静态装饰柱用 <strong>mergeGeometries（静态烘焙，≈1 calls）</strong>；需要独立运动与拾取的树用 <strong>InstancedMesh（≈1 calls，逐实例矩阵 + instanceId 拾取）</strong>。独立 Mesh 都会产生约 2000 次 draw call。</li><li><strong><code>instanced.instanceMatrix.needsUpdate = true</code></strong>（改过颜色还要 <code>instanceColor.needsUpdate = true</code>）。setMatrixAt 只写 CPU 端缓冲数组，需要标记后才会重新上传 GPU。</li><li>逐一释放 <strong>geometry（几何体）、material（材质）、texture（材质引用的贴图）</strong> 三类资源的 <code>dispose()</code>；之后查看 <strong><code>renderer.info.memory</code>（配合 render.calls/triangles）</strong> 确认资源真正回收。</li></ol></details><hr><h2 id="系列完结" tabindex="-1">系列完结 <a class="header-anchor" href="#系列完结" aria-label="Permalink to &quot;系列完结&quot;">​</a></h2><p>至此 11 话走完：<strong>场景 → 场景图 → 相机 → 渲染循环 → 几何体 → 材质 → 纹理 → 灯光阴影 → 动画 → 交互 → 整合优化</strong>。回看 EP.01 的黑屏四件套，你现在已经能独立搭出一座有光照、有动画、能交互、跑得动的三维城市。祝渲染愉快。</p>`,27)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
